INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_b98287f6f80fe431a71209', 'Runway guardrails - Q4 commitments', 'leonard.hayes@harmonygames.co', '["robert@harmonygames.co", "arthur.blake@harmonygames.co", "frederick.stone@harmonygames.co"]', 'private', E'Runway guardrails - Q4 commitments\nLeonard, Sep 26. Until we know where the raise lands, this is how we handle anything outside the investor work that wants money, a signature or an answer from us.\nHow to decide\nGo top to bottom and stop at the first one that fits.\n1. Already answered. If one of us has already given them an answer, don''t write to them again. Note who answered and when. If the answer was "later", it comes back at the January commitments review I''ll put on our calendars too.\n2. Cash test. Anything that would cost us cash between Oct 1 and Dec 31 ends now: say no, or cancel it in writing the way their paper or notice asks. A trial or pilot that turns into a paid plan inside that window counts as cash, and so does an offer we would have to take up and pay for before January. Travel and event costs count only when we book them ourselves.\n3. Keep. The cash test has one exception: anything on Arthur''s keep-running list on our board stays, even if it costs money. Tell them we''re staying.\n4. Sign. If it costs nothing before January but taking it means someone has to accept terms or sign for the company, it goes the way ESG''s note says. Tell them it''s with Leonard or Arthur to sign, and with our lawyers first when ESG has to see it.\n5. Park. Everything else that''s free until January, including offers we could still take up after that. Tell them we''ll pick it up in January; it comes back at the January commitments review I''ll put on our calendars (first week of January).\nAnswers\nEveryone who is waiting to hear from us gets a written answer. Portals and no-reply notices don''t need one.', '[{"start": 0, "end": 35, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 35, "end": 198, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 198, "end": 212, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 212, "end": 1502, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 1502, "end": 1510, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 1510, "end": 1617, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '0d3b4ff7c7', 'f_b98287f6f80fe431a71209', '2025-09-26T16:00:00Z', '2025-09-26T18:00:00Z');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_7bacf15c4e8eea1a52dcd4', 'UA spend buckets (Q4)', 'frederick.stone@harmonygames.co', '["leonard.hayes@harmonygames.co"]', 'private', E'UA spend buckets (Q4)\nFred, Sep 16, after Monday''s exec chat.\nFundraising bucket: incent spend that moves the D1/D7 numbers investors ask about. Adjoe for now. This is the only UA spend that runs until the raise.\nReal UA bucket: Unity, Meta, playables. Budgets set week by week until we know about the raise; playables count here, not in the fundraising bucket.\nReview the split at the exec sync every Monday.', '[{"start": 0, "end": 22, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 22, "end": 409, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '474162b554', 'f_7bacf15c4e8eea1a52dcd4', '2025-09-16T17:00:00Z', '2025-09-16T17:00:00Z');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_3b06917a41dd59308d890b', 'ESG Law - agreement intake checklist', 'leonard.hayes@harmonygames.co', '["robert@harmonygames.co", "arthur.blake@harmonygames.co", "frederick.stone@harmonygames.co"]', 'private', E'ESG Law - agreement intake checklist\nFrom ESG''s call with Leonard, Sep 24. One email per agreement to ESG Law intake.\nInclude\n- the company and what the agreement is\n- the term and any automatic renewal\n- any exclusivity or licence of our IP\n- what it costs us, if anything\n- the date they need it by\n- who would sign it (Leonard or Arthur)', '[{"start": 0, "end": 37, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 37, "end": 118, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 118, "end": 126, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 126, "end": 340, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', 'd96589f49d', 'f_3b06917a41dd59308d890b', '2025-09-25T16:20:00Z', '2025-09-25T16:20:00Z');
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_846ddc38b2aab3d2ed3fcb', 'README - Q4 commitments', 'leonard.hayes@harmonygames.co', '["frederick.stone@harmonygames.co"]', 'private', E'README - Q4 commitments\nLeonard, Sep 30. One sheet for the vendor and partner backlog, one row per company on it. Name it "Q4 commitments log"; to start, copy the header row from the template sheet.\nColumns\nCompany · Contact · What''s waiting · Decision · Answered by · What we told them · Next date\nDecision is one of: Answered, End, Keep, Sign, Park (the guardrails doc says which).\nAnswered by: who on our side already answered them, for Answered rows.\nNext date: for End, the last day to cancel or say no; for Park and for "later" answers, the January review; for Keep, when it next bills; for Sign, the date they need it by, if any.\nContacts\nPut the company in the job field, and only add someone who isn''t in Contacts already.', '[{"start": 0, "end": 24, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 24, "end": 199, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 199, "end": 207, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 207, "end": 637, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}, {"start": 637, "end": 646, "named_style": "HEADING_2", "list_id": null, "list_nesting": 0}, {"start": 646, "end": 731, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', 'e3bed806d2', 'f_846ddc38b2aab3d2ed3fcb', '2025-09-30T22:40:00Z', '2025-09-30T22:40:00Z');
