VALUES ('leonard.hayes@harmonygames.co/<CAlIXcq3nWlSRBAZONcbY9d2v0ggkPYER8WfaoZa@mail.gmail.com>', 'leonard.hayes@harmonygames.co/1844732913254960629', 'leonard.hayes@harmonygames.co', '["SENT"]', 'Fred, I''m in LA from tomorrow for Dentsu and the Griffin AGM, so can you take over the vendor and partner backlog this week? That''s anyone o', 1759274400000, '2025-09-30T23:20:00Z', 2020, 'Vendor and partner stuff while I''m in LA', 'leonard.hayes@harmonygames.co', 'Leonard Hayes', '["Frederick Stone <frederick.stone@harmonygames.co>"]', '[]', '[]', '[]', E'Fred,\r\n\r\nI''m in LA from tomorrow for Dentsu and the Griffin AGM, so can you take over the vendor and partner backlog this week? That''s anyone outside the investor work who has an offer, a trial, a quote, terms or an ask in front of us and that one of us has actually engaged with: a call, a reply, a sign-up or paper. Cold pitches nobody answered, including ones we only forwarded around internally, stay off it, and so do the ad networks, PlayableX, Craftsman+ and Singular (they all stay on the UA budget call), the investors, and Mattel, which I''m keeping.\r\n\r\nGo by the runway guardrails doc for what we do with each one, plus the one change I posted in #executives on Monday. Anything that needs signing goes the way ESG''s note about signing says.\r\n\r\nEveryone who is waiting to hear from us should get a written answer this week. Get each company''s contact into Contacts so we''re not digging through mail next time.\r\n\r\nLog it all in a sheet in the Q4 commitments folder, the README in the folder has the columns. Then reply here with what we''re keeping and what''s waiting on Arthur or me to sign.\r\n\r\nThanks,\r\nLeonard', NULL, '[{"name": "Message-ID", "value": "<CAlIXcq3nWlSRBAZONcbY9d2v0ggkPYER8WfaoZa@mail.gmail.com>"}, {"name": "Date", "value": "Tue, 30 Sep 2025 23:20:00 +0000"}, {"name": "Subject", "value": "Vendor and partner stuff while I''m in LA"}, {"name": "From", "value": "Leonard Hayes <leonard.hayes@harmonygames.co>"}, {"name": "To", "value": "Frederick Stone <frederick.stone@harmonygames.co>"}]', NULL, NULL, NULL, '[]');
INSERT INTO gmail.gmail_threads (id, user_email, snippet, history_id)
VALUES ('frederick.stone@harmonygames.co/1844177063117059830', 'frederick.stone@harmonygames.co', 'Hi Leonard, Following up on our call today, here''s how we''d like agreements handled from now on while you''re raising: - Only an officer, you', NULL);
INSERT INTO gmail.gmail_messages (id, thread_id, user_email, label_ids_json, snippet, internal_date, date, size_estimate, subject, from_email, from_name, to_json, cc_json, bcc_json, reply_to_json, body_text, body_html, headers_json, in_reply_to, "references", mbox_from, attachments_meta_json)
VALUES ('frederick.stone@harmonygames.co/<CAyKP29rjypyVF_dZsTX0hDpFvI5fgxGX5-KMwIz@mail.gmail.com>', 'frederick.stone@harmonygames.co/1844177063117059830', 'frederick.stone@harmonygames.co', '["INBOX", "CATEGORY_PERSONAL"]', 'Hi Leonard, Following up on our call today, here''s how we''d like agreements handled from now on while you''re raising: - Only an officer, you', 1758744300000, '2025-09-24T20:05:00Z', 1580, 'Signing and review for Harmony Games agreements', 'PERSON_2694_EMAIL', 'PERSON_2694_NAME', '["Leonard Hayes <leonard.hayes@harmonygames.co>"]', '["Frederick Stone <frederick.stone@harmonygames.co>", "Robert <robert@harmonygames.co>", "Arthur Blake <arthur.blake@harmonygames.co>"]', '[]', '[]', E'Hi Leonard,\r\n\r\nFollowing up on our call today, here''s how we''d like agreements handled from now on while you''re raising:\r\n\r\n- Only an officer, you or Arthur, accepts terms or signs for Harmony Games, whatever the amount. That includes click-through terms and portal NDAs.\r\n- Anything with an automatic renewal, exclusivity, a licence of your IP or a term over 12 months comes to us before anyone signs. Send each one to our intake address (it''s in your Contacts as ESG Law intake), one email per agreement, so we can open a matter for it.\r\n- Mutual NDAs on our template don''t need review, whatever their term. An officer can sign them.\r\n\r\nBest,\r\nPERSON_2694_NAME\r\nPARTNER, ESG Law', NULL, '[{"name": "Message-ID", "value": "<CAyKP29rjypyVF_dZsTX0hDpFvI5fgxGX5-KMwIz@mail.gmail.com>"}, {"name": "Date", "value": "Wed, 24 Sep 2025 20:05:00 +0000"}, {"name": "Subject", "value": "Signing and review for Harmony Games agreements"}, {"name": "From", "value": "PERSON_2694_NAME <PERSON_2694_EMAIL>"}, {"name": "To", "value": "Leonard Hayes <leonard.hayes@harmonygames.co>"}, {"name": "Cc", "value": "Frederick Stone <frederick.stone@harmonygames.co>, Robert <robert@harmonygames.co>, Arthur Blake <arthur.blake@harmonygames.co>"}]', NULL, NULL, NULL, '[]');
