VALUES ('frederick.stone@harmonygames.co/<CAyZDYLgzExhQkAm-LGcRvcnmhRj4gYsOAVITlO5@mail.gmail.com>', 'frederick.stone@harmonygames.co/1844177063117059830', 'frederick.stone@harmonygames.co', '["INBOX", "CATEGORY_PERSONAL"]', 'Agreed. This replaces what I said in July about Fred signing small stuff himself. Fred, Arthur: anything waiting on Arthur or me to sign, pu', 1758817800000, '2025-09-25T16:30:00Z', 1246, 'Re: Signing and review for Harmony Games agreements', 'leonard.hayes@harmonygames.co', 'Leonard Hayes', '["PERSON_2694_NAME <PERSON_2694_EMAIL>"]', '["Frederick Stone <frederick.stone@harmonygames.co>", "Robert <robert@harmonygames.co>", "Arthur Blake <arthur.blake@harmonygames.co>"]', '[]', '[]', E'Agreed. This replaces what I said in July about Fred signing small stuff himself.\r\n\r\nFred, Arthur: anything waiting on Arthur or me to sign, put it on our founders'' board To Do list with the company''s name in the card title, including the ones that go to ESG. For the intake emails, what to include is in the intake checklist I shared.\r\n\r\nLeonard', NULL, '[{"name": "Message-ID", "value": "<CAyZDYLgzExhQkAm-LGcRvcnmhRj4gYsOAVITlO5@mail.gmail.com>"}, {"name": "Date", "value": "Thu, 25 Sep 2025 16:30:00 +0000"}, {"name": "Subject", "value": "Re: Signing and review for Harmony Games agreements"}, {"name": "From", "value": "Leonard Hayes <leonard.hayes@harmonygames.co>"}, {"name": "To", "value": "PERSON_2694_NAME <PERSON_2694_EMAIL>"}, {"name": "Cc", "value": "Frederick Stone <frederick.stone@harmonygames.co>, Robert <robert@harmonygames.co>, Arthur Blake <arthur.blake@harmonygames.co>"}, {"name": "In-Reply-To", "value": "<CAyKP29rjypyVF_dZsTX0hDpFvI5fgxGX5-KMwIz@mail.gmail.com>"}, {"name": "References", "value": "<CAyKP29rjypyVF_dZsTX0hDpFvI5fgxGX5-KMwIz@mail.gmail.com>"}]', '<CAyKP29rjypyVF_dZsTX0hDpFvI5fgxGX5-KMwIz@mail.gmail.com>', '<CAyKP29rjypyVF_dZsTX0hDpFvI5fgxGX5-KMwIz@mail.gmail.com>', NULL, '[]');
