INSERT INTO gmail.gmail_messages (id, thread_id, user_email, label_ids_json, snippet, internal_date, date, size_estimate, subject, from_email, from_name, to_json, cc_json, bcc_json, reply_to_json, body_text, body_html, headers_json, in_reply_to, "references", mbox_from, attachments_meta_json)
VALUES ('frederick.stone@harmonygames.co/<CAYV6MxN9j-x1B7nyXxQQO_hYhY5AoRuc5G7XzgR@paylane.io>', 'frederick.stone@harmonygames.co/1843067564852153540', 'frederick.stone@harmonygames.co', '["INBOX", "CATEGORY_UPDATES"]', 'Hello, The pilot on workspace HG-2291 (UGC Studio) has reached its 20-video cap. Under your agreement the pilot now ends on Oct 15, 2025 and', 1757686200000, '2025-09-12T14:10:00Z', 1245, 'Workspace HG-2291: your pilot is ending', 'SVC_9701_EMAIL', 'Paylane', '["Frederick Stone <frederick.stone@harmonygames.co>"]', '[]', '[]', '[]', E'Hello,\r\n\r\nThe pilot on workspace HG-2291 (UGC Studio) has reached its 20-video cap. Under your agreement the pilot now ends on Oct 15, 2025 and the Studio plan starts on Oct 16 at $1,800/month.\r\n\r\nTo cancel before the plan starts, write to billing@paylane.io by Oct 15. Replies to this email aren''t monitored.\r\n\r\nPaylane, payments for UGC Studio', NULL, '[{"name": "Message-ID", "value": "<CAYV6MxN9j-x1B7nyXxQQO_hYhY5AoRuc5G7XzgR@paylane.io>"}, {"name": "Date", "value": "Fri, 12 Sep 2025 14:10:00 +0000"}, {"name": "Subject", "value": "Workspace HG-2291: your pilot is ending"}, {"name": "From", "value": "Paylane <SVC_9701_EMAIL>"}, {"name": "To", "value": "Frederick Stone <frederick.stone@harmonygames.co>"}]', NULL, NULL, NULL, '[]');
INSERT INTO gmail.gmail_threads (id, user_email, snippet, history_id)
VALUES ('frederick.stone@harmonygames.co/1843618067251203081', 'frederick.stone@harmonygames.co', 'Hi Frederick, Thanks for the call on Tuesday. As promised, the order form for Pro is attached: 4 seats, unlimited template and stock-clip do', NULL);
INSERT INTO gmail.gmail_messages (id, thread_id, user_email, label_ids_json, snippet, internal_date, date, size_estimate, subject, from_email, from_name, to_json, cc_json, bcc_json, reply_to_json, body_text, body_html, headers_json, in_reply_to, "references", mbox_from, attachments_meta_json)
VALUES ('frederick.stone@harmonygames.co/<CAGJkuaxoKn_J2zxTzhLswrYwOGA_wA5IXe9v747@mail.gmail.com>', 'frederick.stone@harmonygames.co/1843618067251203081', 'frederick.stone@harmonygames.co', '["INBOX", "CATEGORY_PERSONAL"]', 'Hi Frederick, Thanks for the call on Tuesday. As promised, the order form for Pro is attached: 4 seats, unlimited template and stock-clip do', 1758211200000, '2025-09-18T16:00:00Z', 1216, 'Framewell Pro for Harmony Games', 'PERSON_9701_EMAIL', 'Maren Holt', '["Frederick Stone <frederick.stone@harmonygames.co>"]', '[]', '[]', '[]', E'Hi Frederick,\r\n\r\nThanks for the call on Tuesday. As promised, the order form for Pro is attached: 4 seats, unlimited template and stock-clip downloads. Pro starts Nov 1 at $149/month, billed monthly, and you keep the free seat until then.\r\n\r\nCan you let me know by mid-October if we should set it up?\r\n\r\nBest,\r\nMaren', NULL, '[{"name": "Message-ID", "value": "<CAGJkuaxoKn_J2zxTzhLswrYwOGA_wA5IXe9v747@mail.gmail.com>"}, {"name": "Date", "value": "Thu, 18 Sep 2025 16:00:00 +0000"}, {"name": "Subject", "value": "Framewell Pro for Harmony Games"}, {"name": "From", "value": "Maren Holt <PERSON_9701_EMAIL>"}, {"name": "To", "value": "Frederick Stone <frederick.stone@harmonygames.co>"}]', NULL, NULL, NULL, '[]');
INSERT INTO gmail.gmail_threads (id, user_email, snippet, history_id)
VALUES ('frederick.stone@harmonygames.co/1844157874176168845', 'frederick.stone@harmonygames.co', 'Hi Frederick, Heads-up that the free Starter tier on your account ends on Oct 31. From Nov 1 the account moves to Team ($29/month) under you', NULL);
INSERT INTO gmail.gmail_messages (id, thread_id, user_email, label_ids_json, snippet, internal_date, date, size_estimate, subject, from_email, from_name, to_json, cc_json, bcc_json, reply_to_json, body_text, body_html, headers_json, in_reply_to, "references", mbox_from, attachments_meta_json)
VALUES ('frederick.stone@harmonygames.co/<CAZgisbRwHgHd3Hk_E9LYMNIOFiMZminBj4K2tWc@mail.gmail.com>', 'frederick.stone@harmonygames.co/1844157874176168845', 'frederick.stone@harmonygames.co', '["INBOX", "CATEGORY_PERSONAL"]', 'Hi Frederick, Heads-up that the free Starter tier on your account ends on Oct 31. From Nov 1 the account moves to Team ($29/month) under you', 1758726000000, '2025-09-24T15:00:00Z', 1326, 'Your Pingwise Starter tier ends Oct 31', 'PERSON_9703_EMAIL', 'Dana Whitfield', '["Frederick Stone <frederick.stone@harmonygames.co>"]', '[]', '[]', '[]', E'Hi Frederick,\r\n\r\nHeads-up that the free Starter tier on your account ends on Oct 31. From Nov 1 the account moves to Team ($29/month) under your existing agreement, so phone and SMS paging keep working for your on-call rota. If you''d rather drop back to the free plan, reply and I''ll downgrade you before then. Free has email alerts only, no paging.\r\n\r\nCan you confirm either way?\r\n\r\nDana Whitfield\r\nCustomer Success, Pingwise', NULL, '[{"name": "Message-ID", "value": "<CAZgisbRwHgHd3Hk_E9LYMNIOFiMZminBj4K2tWc@mail.gmail.com>"}, {"name": "Date", "value": "Wed, 24 Sep 2025 15:00:00 +0000"}, {"name": "Subject", "value": "Your Pingwise Starter tier ends Oct 31"}, {"name": "From", "value": "Dana Whitfield <PERSON_9703_EMAIL>"}, {"name": "To", "value": "Frederick Stone <frederick.stone@harmonygames.co>"}]', NULL, NULL, NULL, '[]');
