VALUES ('frederick.stone@harmonygames.co/<CAyIhcf4XSg_rUt0eT-St8La39wsNDnRzBlIxJMi@mail.gmail.com>', 'frederick.stone@harmonygames.co/1837102635418059486', 'frederick.stone@harmonygames.co', '["INBOX", "CATEGORY_PERSONAL"]', 'Hi Frederick, Welcome aboard! Your UGC Studio pilot workspace is set up (HG-2291) and the pilot agreement is attached. Looking forward to th', 1751997600000, '2025-07-08T18:00:00Z', 1124, 'Clipforge UGC Studio pilot - welcome', 'PERSON_9704_EMAIL', 'Priya Raman', '["Frederick Stone <frederick.stone@harmonygames.co>"]', '[]', '[]', '[]', E'Hi Frederick,\r\n\r\nWelcome aboard! Your UGC Studio pilot workspace is set up (HG-2291) and the pilot agreement is attached. Looking forward to the kickoff on Monday the 14th, bring a couple of briefs if you have them.\r\n\r\nPriya', NULL, '[{"name": "Message-ID", "value": "<CAyIhcf4XSg_rUt0eT-St8La39wsNDnRzBlIxJMi@mail.gmail.com>"}, {"name": "Date", "value": "Tue, 08 Jul 2025 18:00:00 +0000"}, {"name": "Subject", "value": "Clipforge UGC Studio pilot - welcome"}, {"name": "From", "value": "Priya Raman <PERSON_9704_EMAIL>"}, {"name": "To", "value": "Frederick Stone <frederick.stone@harmonygames.co>"}]', NULL, NULL, NULL, '[]');
