INSERT INTO linear.linear_issues (id, project_id, team_id, parent_id, assignee_id, creator_id, state_id, cycle_id, identifier, number, title, description, priority, estimate, due_date, started_at, completed_at, canceled_at, archived_at, time_in_status_minutes, labels_json, links_json, relations_json, state_history_json, is_archived, created_at, updated_at)
VALUES ('ZOM-567', NULL, 'team_ZOM', NULL, NULL, 'usr_cc3e90160f490686', 'Todo', NULL, 'ZOM-567', 567, 'Switch: order dev kits', 'Fred registered us on the Nintendo developer portal on Sep 4. Next step is ordering dev kits ($400-500 per kit per the portal) so we can try a Zombie Match 3D port.', 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', '[]', '[]', false, '2025-09-23T17:00:00Z', '2025-09-25T18:20:00Z');
INSERT INTO linear.linear_comments (id, issue_id, author_id, parent_id, body, is_edited, created_at, updated_at, sequence)
VALUES ('cmt_c9a6660d81e067ad1de7', 'ZOM-567', 'usr_cc3e90160f490686', NULL, 'Tried to order the kits today. The portal won''t take an order yet: the Global ToS and NDA still needs our agreement approver to accept it, and that has to be a company officer from their own login. Fred is only set up as administrator, so the ''NDA Effective 09/04'' on his registration mail is just the start date it will carry. It''s Nintendo''s standard click-through: no fee, no exclusivity, nothing about our IP, and either side can end it. It has to be accepted by Oct 15 or the request lapses. The kits can wait until after the raise; leaving the acceptance for Leonard or me.', false, '2025-09-25T18:20:00Z', '2025-09-25T18:20:00Z', 1);
